/**
 * Icons playhound ships for its own plugins (src/assets/plugins, generated by
 * brand/v2/make-plugin-icons.mjs), for releases that don't carry one yet.
 * Only a plugin from an official repository gets one: a plugin from anywhere
 * else that happens to use the same id keeps its own icon or its initials.
 * A plugin's own icon, when it has one, always wins (see PluginIcon).
 */
const files = import.meta.glob<string>('../assets/plugins/*.svg', { eager: true, query: '?url', import: 'default' })

const BUILT_IN: Record<string, string> = Object.fromEntries(
  Object.entries(files).map(([file, url]) => [file.replace(/^.*\/|\.svg$/g, ''), url]),
)

/** The built-in icon for plugin `id`, when it is one of playhound's own (`official`); else null. */
export function builtInIcon(id: string, official: boolean): string | null {
  return official && Object.hasOwn(BUILT_IN, id) ? BUILT_IN[id] : null
}
